// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the arrays' lengths and a single recipient/amount; the fuzzer will explore inputs
    function testFuzz_property(address to, uint256 v) public {
        // Keep a simple admissible domain: to must be non-zero and not the special from address
        vm.assume(to != address(0));
        // build single-element arrays to call transfer
        address[] memory tos = new address[](1);
        tos[0] = to;
        uint[] memory vals = new uint[](1);
        vals[0] = v;

        // call transfer and capture whether it returns true (ok == true) or false / reverts (ok == false)
        bool ok;
        try c.transfer(tos, vals) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        // General rule: for any admissible input that does not revert, the reference returns true.
        // We assert that the call returned true (if it completed). If it reverted, ok==false and the assertion
        // will fail only when the mutant returns false for some inputs that the reference would return true on.
        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: an array length and a single recipient address and a uint value
    // we cannot fuzz an array directly easily here, so we fuzz a single address and a uint and
    // construct a 1-element array to keep domain wide. This lets fuzzer find inputs that complete.
    function testFuzz_property(address to, uint256 v) public {
        // admissible domain: must be called by the required sender and arrays must be non-empty
        // keep domain wide: require to != address(0) to avoid trivial zero-address constraints
        vm.assume(to != address(0));
        // construct 1-element arrays
        address[] memory tos = new address[](1);
        tos[0] = to;
        uint[] memory vals = new uint[](1);
        vals[0] = v;

        // call as the required sender
        address sender = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.prank(sender);

        // perform the call and capture whether it completed (did not revert) and its return value
        bool ok;
        bool ret;
        try c.transfer(tos, vals) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        // The reference contract always returns true for any admissible call that completes.
        // We therefore assert that if the call completed, the returned value is true.
        assertTrue(!ok || ret);
    }
}

