pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the arrays (addresses and uints). The deciding parameter is that _tos.length > 0
    // We let the fuzzer supply arrays; ensure they are non-empty to hit the behavioral difference.
    function testFuzz_property(address[] memory tos, uint256[] memory vals) public {
        // keep wide but ensure non-empty to exercise the differing branch
        vm.assume(tos.length > 0);
        // align lengths so the reference will iterate safely
        // If vals is shorter, bound it by copying/expanding to match tos length
        if (vals.length < tos.length) {
            uint256[] memory expanded = new uint256[](tos.length);
            for (uint i = 0; i < tos.length; i++) {
                if (i < vals.length) expanded[i] = vals[i]; else expanded[i] = 0;
            }
            vals = expanded;
        }

        // call transfer and capture whether it returns successfully (does not revert)
        bool ok;
        try c.transfer(tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: For any non-empty tos the reference implementation returns true (call completes).
        // The mutant that requires tos.length == 0 will fail (revert) for some non-empty inputs; thus
        // assertTrue(ok) will pass on the reference for all such inputs and fail on the mutant for at least one.
        assertTrue(ok);
    }
}

