        bool ok;
        try c.transfer(_tos, v) returns (bool res) {
            // record success if the call completed and returned true
            ok = res;
        } catch {
            ok = false;
        }

        // The reference C always returns true (completes successfully) for any input when called by designated
        // (this is the universal property we assert). The mutant that flips the length check will fail for some
        // non-empty _tos arrays; the fuzzer should find such an input causing this assert to fail on the mutant.
        assertTrue(ok);
    }
}

