pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the arrays of addresses and values. The reference contract accepts calls from its fixed sender
    // and (for admissible inputs) always completes successfully returning true; the mutant that requires
    // _tos.length == 0 will cause some non-empty arrays to behave differently. We must ensure the caller
    // is the designated sender recorded in C, so we prank to that address.
    function testFuzz_property(address[] memory _tos, uint256[] memory v) public {
        // admissible domain: arrays must have same length and length fits in reasonable bounds
        vm.assume(_tos.length == v.length);
        // keep lengths bounded to avoid excessive gas in fuzz runs
        uint256 maxLen = 10;
        if (_tos.length > maxLen) {
            // shrink by taking prefix
            assembly { mstore(_tos, maxLen) }
            assembly { mstore(v, maxLen) }
        }

        // The contract C expects msg.sender == 0x9797... so we prank as that address
        address designated = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.startPrank(designated);
        bool ok;
        // call and catch revert to observe completion vs revert
        try c.transfer(_tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // The single universal assertion: for all admissible inputs (same-length arrays, caller is designated),
        // the reference implementation always completes successfully (returns true). The buggy mutant that
        // requires _tos.length == 0 will make some non-empty inputs cause ok == false; thus this assertion
        // holds for the reference and will fail on the mutant for some fuzz inputs.
        assertTrue(ok);
    }
}

