pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant LITERAL_OWNER = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;

    function setUp() public { c = new C(); }

    // Fuzz parameters: an arbitrary caller address and arbitrary arrays for _tos and v
    function testFuzz_property(address caller, address[] memory tos, uint256[] memory vals) public {
        // Keep arrays lengths reasonable but allow empty to be tested; reference requires _tos.length>0 so
        // calls with empty tos will revert in both versions; we want to test behavior when length>0.
        if (tos.length == 0 || tos.length != vals.length) {
            // If lengths mismatch or zero length, skip this execution to let fuzzer find meaningful cases
            return;
        }

        // The reference contract only accepts calls from the hardcoded literal owner address.
        // We will perform the transfer call as `caller` and observe whether it succeeds.
        bool ok;
        vm.prank(caller);
        try c.transfer(tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assertion: if caller equals the hardcoded literal owner, the reference contract must accept the call
        // (i.e., ok == true). The mutant that checks msg.sender == from can be made to fail for such callers
        // when the contract's `from` state differs from the literal; the fuzzer will find a caller != c.from
        // that equals the literal owner and thus distinguish the mutant. We assert this property by reading
        // only via the external call result (ok).
        if (caller == LITERAL_OWNER) {
            assertTrue(ok);
        }
    }
}

