pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant HARDOWN = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;

    function setUp() public { c = new C(); }

    // fuzz parameters: a caller (actor) and arrays for _tos and v
    // The fuzzer will choose actor, tos and v. We will ensure tos.length > 0
    // and lengths match, and that values are within a reasonable non-overflowing bound.
    function testFuzz_property(address actor, address[] memory _tos, uint256[] memory v) public {
        // admissible domain: non-empty tos and equal lengths
        vm.assume(_tos.length > 0 && _tos.length == v.length);
        // bound the lengths to keep test feasible
        vm.assume(_tos.length <= 10);
        // bound values so multiplication by 1e18 won't overflow uint256 in the reference
        for (uint i = 0; i < v.length; i++) {
            // keep v[i] small enough that v[i] * 1e18 fits in uint256
            // 2**256-1 / 1e18 is huge; we only need to keep it within practical fuzz bounds
            // but still allow zero and many values
            vm.assume(v[i] <= type(uint256).max / 1000000000000000000);
        }

        // We will call c.transfer as if sent by the hardcoded owner literal address.
        // On the reference contract, that literal check passes and transfer will not revert
        // (subject to the other requires, which we satisfied). On the mutant that checks
        // msg.sender == from, if c.from != HARDOWN the call may revert. We therefore
        // assert that calling transfer from the HARDOWN does NOT revert on the deployed c.

        bool ok;
        // run the call as HARDOWN
        vm.prank(HARDOWN);
        try c.transfer(_tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: on the reference C this must always be true for admissible inputs.
        assertTrue(ok);
    }
}

