        predicted = address(uint160(uint256(hash)));
        // ensure predicted matches the target address
        require(predicted == 0x1f844685f7Bf86eFcc0e74D8642c54A257111923, "predicted != target");
        address addr;
        assembly {
            addr := create2(0, add(initCode, 0x20), mload(initCode), salt)
