contract CalleeHelper {
    uint256 public callCount;
    constructor() {
        callCount = 0;
    }
    // accept any calldata and increment counter
    fallback() external payable {
        callCount += 1;
    }
    receive() external payable {
        callCount += 1;
    }
    function reset() external {
        callCount = 0;
    }
}

