// Minimal helper callee that increments a counter on any call
contract HelperCallee {
    uint256 public callCount;
    function reset() external { callCount = 0; }
    receive() external payable { callCount += 1; }
    fallback() external payable { callCount += 1; }
}

// Minimal factory used to try to deploy HelperCallee at the fixed target address using CREATE2.
contract Factory {
    function deployAt(address target) external returns (bool) {
        // try salts until we find one or exhaust a small range
        bytes memory initcode = type(HelperCallee).creationCode;
        for(uint256 salt = 0; salt < 1000; salt++) {
            address addr;
            assembly {
                addr := create2(0, add(initcode, 0x20), mload(initcode), salt)
            }
            if (addr == target) return true;
            // if deployed at other addr, skip
        }
        return false;
    }
}

