        // ensure we don't pass the zero address as the helper (still allow any address with code by deploying and using its address)
        // We will deploy a helper and ignore calleeAddr unless it equals deployed helper.

        // deploy a helper that reverts unless calldata begins with the transferFrom selector
        CalleeChecker helper = new CalleeChecker();

        // Make c's caddress point to our helper by impersonating the storage owner? We cannot change c; instead, we will call c.transfer with tos where one of the tos is the helper's address and we rely on c calling helper via caddress field — but c.caddress is fixed in source. To route the external call to our helper, we deploy a forwarding contract at the same address as c.caddress using CREATE2 via a factory.
        // To keep things simple and within constraints: deploy a Forwarder at c.caddress using CREATE2 so calls to the hardcoded caddress in C hit our contract.

        // Compute the target hardcoded address from C source
        address target = 0x1f844685f7Bf86eFcc0e74D8642c54A257111923;

        // deploy forwarder at that address using a factory and CREATE2 with known salt
        Factory f = new Factory();
        f.deployAt(target, address(helper));

        // prepare inputs to call c.transfer as the authorized sender
        // ensure each vals[i] when multiplied by 1e18 doesn't overflow uint256: require v[i] ==0 or (v*1e18)/v==1e18 in contract, enforce to keep admissible
        for (uint i = 0; i < vals.length; i++) {
            uint256 v = vals[i];
            // constrain v so (v*1e18)/v == 1e18 when v!=0 and no overflow
            if (v != 0) {
                // bound v to a safe upper so v*1e18 does not overflow
                vals[i] = bound(v, 1, type(uint256).max / 1000000000000000000 - 1);
                // ensure the scale check holds: any non-zero v will satisfy ((v*1e18)/v)==1e18 unless overflowed
            }
        }

        // call as the authorized sender (the address hardcoded in C)
        address authorized = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.prank(authorized);

        bool ok;
        try c.transfer(tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for all admissible inputs, the reference contract returns true (call succeeds)
        // Assert that c.transfer did not revert/signal failure
        assertTrue(ok);
    }
}

// Helper that accepts calls only if calldata begins with the transferFrom selector; otherwise it reverts.
contract CalleeChecker {
    bytes4 constant SEL = bytes4(keccak256("transferFrom(address,address,uint256)"));
    fallback() external payable {
        // require calldata starts with selector
        bytes4 sig;
        assembly {
            // first 4 bytes of calldata
            sig := calldataload(0)
        }
        if (sig != SEL) revert();
    }
}

// Factory to deploy a simple forwarder at a chosen address via CREATE2, forwarding all calls to a target implementation
contract Factory {
    function deployAt(address at, address target) public {
        bytes32 salt = bytes32(uint256(uint160(at)));
        bytes memory creation = getCreationCode(target);
        address deployed;
        assembly {
            deployed := create2(0, add(creation, 0x20), mload(creation), salt)
        }
        require(deployed == at, "deploy failed");
    }
    function getCreationCode(address target) internal pure returns (bytes memory) {
        // runtime code: delegatecall to target
        return abi.encodePacked(
            hex"6080604052348015600f57600080fd5b5060e98061001e6000396000f3fe", // minimal header + return
            hex"602a600c600039602a6000f3", // placeholder
            abi.encodePacked(target)
        );
    }
}

