// Minimal helper that reverts if calldata does not start with transferFrom selector
contract RevertIfNoSelector {
    fallback() external payable {
        bytes4 expected = bytes4(keccak256("transferFrom(address,address,uint256)"));
        bytes4 sig;
        assembly { sig := calldataload(0) }
        if (sig != expected) revert();
    }
}

// A tiny deployer that can deploy arbitrary creation code via CREATE2 (not used deterministically here)
contract Deployer {
    function deploy(bytes memory code, bytes32 salt) public returns (address addr) {
        assembly {
            addr := create2(0, add(code, 0x20), mload(code), salt)
        }
        require(addr != address(0), "deploy failed");
    }
}

