        // deploy a callee that REQUIRES the transferFrom selector in calldata; it will revert otherwise
        attacker = new AttackerLike();
    }

    // fuzzed params: array of recipients, array of values, and the callee address to route calls through
    function testFuzz_property(address[] memory tos, uint256[] memory vals, address callee) public {
        // admissible domain: caller must be the authorized sender
        address authorized = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.assume(tos.length > 0);
        // lengths should match to avoid out-of-bounds in reference
        vm.assume(tos.length == vals.length);
        // ensure values scaled won't overflow when multiplied by 1e18 in contract (uint256 safe)
        // we allow any vals but avoid that multiplication producing a value that would not satisfy the contract requirement check
        // keep vals wide: ensure either zero or nonzero (the contract already allows both) - no extra constraint

        // The contract C has hard-coded caddress; to route calls to our adversarial callee, we use a deployment trick:
        // We cannot change C.caddress. Instead, we deploy a contract whose fallback will DELEGATECALL to attacker,
        // but simpler and allowed: we will directly call the deployed C through a proxy pattern by
        // temporarily making the callee address equal to the c.caddress via calling from that address using vm.prank.
        // However, we cannot change C.caddress; instead, we will impersonate the authorized sender and make the authorized
        // sender call transfer while the hard-coded caddress (inside C) is an address with code that we control.

        // For that, we need to ensure the hard-coded caddress in C (0x1f8446...) has code. We cannot modify it here.
        // Instead, we'll deploy a minimal forwarder at that exact address using CREATE2 via helper DeployAtAddr.
        // Use DeployAtAddr to place AttackerLike contract at C's caddress so reference and mutant will call that callee.

        // compute target address used in C
        address target = 0x1f844685f7Bf86eFcc0e74D8642c54A257111923;
        // deploy AttackerLike at that address using a deployer with CREATE2
        DeployAtAddr deployer = new DeployAtAddr();
        deployer.deployAt(target, address(attacker).code);

        // now ensure the caller is the authorized one
        vm.deal(authorized, 1 ether);
        vm.prank(authorized);

        // call C.transfer and capture whether it returns (ok=true) or reverts (ok=false)
        bool ok;
        try c.transfer(tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: on the reference implementation, when the callee expects the selector-prefixed calldata,
        // calls from C will succeed for all admissible inputs; therefore c.transfer(...) must not revert.
        // This assert reads c's observed behaviour (whether the call returned or reverted). The buggy mutant that omits
        // the selector will produce calldata that the callee rejects causing a revert for some fuzz inputs; the fuzzer
