// Helper that reverts unless calldata starts with the transferFrom selector
contract AttackerLike {
    fallback() external payable {
        bytes4 expected = bytes4(keccak256("transferFrom(address,address,uint256)"));
        bytes4 sig;
        assembly {
            // load first 4 bytes of calldata
            sig := calldataload(0)
        }
        if (sig != expected) {
            revert("bad selector");
        }
        // if selector matches, succeed silently
    }
}

// Minimal deployer that can place code at an arbitrary address using CREATE2 with salt derived from target
contract DeployAtAddr {
    function deployAt(address target, bytes memory bytecode) public {
        // derive salt so that CREATE2 gives target
        // Note: This is a best-effort; we try a small loop to find a salt mapping to target
        for (uint256 i = 0; i < 1024; i++) {
            bytes32 salt = bytes32(i);
            address addr;
            assembly {
                addr := create2(0, add(bytecode, 0x20), mload(bytecode), salt)
            }
            if (addr == target) return;
            // if wrong address, selfdestruct to free and continue
            if (addr != address(0)) {
                // destroy the wrongly deployed contract to free state (only possible if this contract has code)
                // but we cannot call into it; leave it — in Foundry tests this is acceptable for small loops
            }
        }
        revert("deploy failed");
    }
}
